1	// Shared game-server order core — the ONE audited debit path for game servers,
2	// used by the wallet flow (lib/actions-gameplans.ts payAndDeployGame /
3	// orderGameServer) AND the Stripe confirm/webhook fulfilment (lib/fulfil-checkout.ts)
4	// so a card-paid game order provisions through the SAME machinery a VPS order does.
5	// Plain server module (NOT "use server") — no secrets, callable from actions,
6	// server components and the worker/webhook alike.
7	//
8	// This is the game analogue of lib/order.ts (orderQuote / placeOrder). It was
9	// factored OUT of the original `orderGameServer` so the card path and the wallet
10	// path settle through one function instead of two copies that could drift.
11	//
12	// MONEY RULES (audited):
13	//   - Prices are strictly DB-fed: `gamePlan.priceCents` is the ONLY source, priced
14	//     through the SAME `termPriceCents` formula the deploy wizard shows and the
15	//     renewal sweep bills (displayed === charged === renewed).
16	//   - Game bills FULL from month 1. There is NO first-month-free on game (that promo
17	//     is Shared-Web-Hosting-only); no $0 path, no coupon, no VAT change here.
18	//   - The wallet is the single debit; `debitWallet` refuses to overdraw.
19	//   - `sold` (card path) carries the price the order was SOLD at, stamped BEFORE the
20	//     card cleared, so fulfilment never re-prices after the money moved (the H2
21	//     incident guarded on lib/order.ts OrderPrice).
22	import { Prisma } from "@prisma/client";
23	import type { User } from "@prisma/client";
24	import { db } from "./db";
25	import { debitWallet, InsufficientBalanceError } from "./wallet";
26	import { addMonths, normalizeProductTerm, termPriceCents, vpsTerm } from "./billing-terms";
27	import { annualDiscountPct } from "./annual-discount";
28	import { capacityCheck } from "./capacity";
29	import { GAME_FAMILIES, type GameFamily } from "./games";
30	import { schemaFor, isValidVariant, validateConfig } from "./game-config";
31	import { recordDeployFunnelComplete } from "./deploy-funnel";
32	
33	export class GameOrderError extends Error {}
34	
35	/** Hostname rules mirror the VPS order path (lib/order.ts orderSchema). */
36	const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
37	
38	/** Short random suffix so auto-generated hostnames don't collide. */
39	export function randSuffix(n = 6): string {
40	  return Math.random().toString(36).slice(2, 2 + n);
41	}
42	
43	/**
44	 * The customer's full game-order intent — the tier, the billing term and the
45	 * per-game setup captured by the wizard. `config` holds the raw gameplay values
46	 * (validated against the family schema in `gameOrderQuote`); `variant` is the
47	 * server type/loader.
48	 */
49	export type GameOrderIntent = {
50	  gamePlanId: string;
51	  /** 1 (Monthly) or 12 (Annual) — normalised through normalizeProductTerm. */
52	  termMonths: number;
53	  /** Optional customer-facing nickname → Server.label. */
54	  serverName?: string;
55	  /** DNS-safe hostname → Server.name/hostname. Blank => auto-generated. */
56	  hostname?: string;
57	  /** Game type/loader id (e.g. "paper", "carbon"); validated per family. */
58	  variant?: string;
59	  /** Raw gameplay settings; validated + coerced against the family schema. */
60	  config?: Record<string, unknown> | null;
61	};
62	
63	/**
64	 * The price a game order was SOLD at, stamped onto the Stripe session BEFORE the
65	 * card was charged and read back at fulfilment. Game has no promo/coupon/tax, so
66	 * this is just the net charge — a deliberately tiny shape (compare lib/order.ts
67	 * OrderPrice, which must also carry promo + VAT).
68	 */
69	export type GameOrderPrice = { chargeCents: number };
70	
71	/** Parse a sold game price back off Stripe metadata; null unless well-formed. */
72	export function parseGameOrderPrice(raw: unknown): GameOrderPrice | null {
73	  let obj: unknown = raw;
74	  if (typeof raw === "string") {
75	    try {
76	      obj = JSON.parse(raw);
77	    } catch {
78	      return null;
79	    }
80	  }
81	  if (!obj || typeof obj !== "object") return null;
82	  const { chargeCents } = obj as Record<string, unknown>;
83	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
84	  return { chargeCents };
85	}
86	
87	export type GameOrderQuote = {
88	  gamePlanId: string;
89	  gameFamily: string;
90	  planName: string;
91	  basePlanId: string;
92	  osTemplateId: string;
93	  /** Normalised term (1 or 12). */
94	  term: number;
95	  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
96	  annualPct: number;
97	  /** DB-fed per-month base (priceCents / termMonths). */
98	  monthlyCents: number;
99	  /** The net charge for the whole term — displayed === charged === renewed. */
100	  chargeCents: number;
101	  hostname: string;
102	  label: string | null;
103	  variant: string;
104	  /** Clean, fully-populated gameplay values ready to persist (may be empty). */
105	  values: Record<string, string | number | boolean>;
106	};
107	
108	/**
109	 * Validate + price a game order without placing it. Throws GameOrderError on any
110	 * problem. Pure of side effects beyond reads. The price is the whole truth about
111	 * what this order costs; the caller (wallet split, review step, checkout stamp)
112	 * quotes from THIS so what the customer sees is what settles.
113	 */
114	export async function gameOrderQuote(intent: GameOrderIntent): Promise<GameOrderQuote> {
115	  const term = normalizeProductTerm(intent.termMonths);
116	
117	  const gp = await db.gamePlan.findUnique({
118	    where: { id: intent.gamePlanId },
119	    include: { basePlan: true },
120	  });
121	  if (!gp || !gp.active) throw new GameOrderError("That game plan isn't available.");
122	  if (!gp.basePlan?.active) throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
123	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
124	    throw new GameOrderError("Unknown game family.");
125	  }
126	
127	  // Resolve the game image: the tier's own OsTemplate, else any active image for
128	  // this family. A game server can't provision without an image.
129	  let osTemplateId = gp.osTemplateId;
130	  if (osTemplateId) {
131	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
132	    if (!os?.active) osTemplateId = null;
133	  }
134	  if (!osTemplateId) {
135	    const os = await db.osTemplate.findFirst({
136	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
137	      orderBy: { sortOrder: "asc" },
138	    });
139	    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
140	    osTemplateId = os.id;
141	  }
142	
143	  // Hostname: validate a provided one strictly, else auto-generate a safe one.
144	  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
145	  let hostname = rawHost;
146	  if (hostname === "") {
147	    hostname = `${gp.gameFamily}-${randSuffix()}`;
148	  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
149	    throw new GameOrderError(
150	      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
151	    );
152	  }
153	
154	  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;
155	
156	  // Per-game setup: variant + gameplay settings, validated against the family
157	  // schema. Families without a customization schema (e.g. Terraria) carry no
158	  // variant and no gameplay values — the wizard shows only identity fields for them.
159	  const schema = schemaFor(gp.gameFamily);
160	  let variant = "";
161	  let values: Record<string, string | number | boolean> = {};
162	  if (schema) {
163	    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
164	    if (!isValidVariant(gp.gameFamily, variant)) {
165	      throw new GameOrderError("Choose a valid server type for this game.");
166	    }
167	    const res = validateConfig(gp.gameFamily, intent.config ?? {});
168	    if (!res.ok) throw new GameOrderError(res.error);
169	    values = res.values;
170	  }
171	
172	  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
173	  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
174	  // divisor keeps the maths correct if a multi-month base plan is ever configured.
175	  const annualPct = await annualDiscountPct();
176	  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
177	  const chargeCents = termPriceCents(monthlyCents, term, annualPct);
178	
179	  return {
180	    gamePlanId: gp.id,
181	    gameFamily: gp.gameFamily,
182	    planName: gp.name,
183	    basePlanId: gp.basePlanId,
184	    osTemplateId,
185	    term,
186	    annualPct,
187	    monthlyCents,
188	    chargeCents,
189	    hostname,
190	    label,
191	    variant,
192	    values,
193	  };
194	}
195	
196	/**
197	 * Place a game order: re-validate + price, capacity-check, then atomically debit
198	 * the wallet and create the Server (sized by the tier's base VPS plan, running the
199	 * game image, with the customer's variant + gameplay settings) plus a PROVISION
200	 * job. Returns the new server id. Does NOT redirect.
201	 *
202	 * `sold` (card path) overrides the recomputed price with the one the order was
203	 * SOLD at — the card-paid path passes the figure stamped on the Checkout session
204	 * BEFORE the card was charged, so the confirm/webhook fulfilment settles the price
205	 * the customer consented to instead of re-pricing against a rate that changed in
206	 * between. The wallet path omits it and pays the fresh quote it computed moments
207	 * ago. This mirrors `sold` in lib/order.ts placeOrder.
208	 *
209	 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
210	 * path is gated by the balance check in the action). This still enforces the
211	 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
212	 */
213	export async function placeGameOrder(
214	  user: User,
215	  intent: GameOrderIntent,
216	  sold?: GameOrderPrice | null,
217	): Promise<string> {
218	  const quote = await gameOrderQuote(intent);
219	
220	  // Bill off the SOLD price when present (never re-priced after the card cleared),
221	  // else the fresh quote. Game has no promo/coupon, so this scalar is the whole
222	  // truth about what this order costs.
223	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
224	
225	  // Oversell guard — the VPS order path enforces this; game orders must too, or a
226	  // game server could commit host RAM past capacity.
227	  const capacity = await capacityCheck(quote.basePlanId);
228	  if (!capacity.ok) {
229	    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
230	  }
231	
232	  // Balance gate BEFORE the tx so we fail cleanly (no money moved). On the card
233	  // path the wallet was credited the card leg first, so this holds.
234	  if (user.balanceCents < chargeCents) {
235	    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
236	  }
237	
238	  const effMonthly = quote.term > 1 ? Math.round(chargeCents / quote.term) : 0;
239	  const termLabel =
240	    quote.term > 1 ? `${vpsTerm(quote.term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(quote.term).label;
241	
242	  let server;
243	  try {
244	    server = await db.$transaction(async (tx) => {
245	      await debitWallet(tx, user.id, chargeCents);
246	      await tx.walletTransaction.create({
247	        data: {
248	          userId: user.id,
249	          amountCents: -chargeCents,
250	          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
251	        },
252	      });
253	      const s = await tx.server.create({
254	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
255	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
256	        data: {
257	          name: quote.hostname,
258	          hostname: quote.hostname,
259	          label: quote.label,
260	          userId: user.id,
261	          planId: quote.basePlanId,
262	          gamePlanId: quote.gamePlanId,
263	          osTemplateId: quote.osTemplateId,
264	          // The customer's per-game setup, applied at the point of sale — the worker
265	          // renders these into the game's own config at provision (worker/game-config).
266	          gameVariant: quote.variant || null,
267	          gameConfig: Object.keys(quote.values).length > 0 ? quote.values : Prisma.JsonNull,
268	          // The chosen term rides the Server row (Monthly / Annual); renewalCharge's
269	          // game branch renews monthlyCents × termMonths × (1 − annual).
270	          termMonths: quote.term,
271	          // No seasonal promo on game — this term was sold at 0% off, so any future
272	          // proration prices against full price.
273	          termPromoPercent: 0,
274	          // The annual rate frozen at sale, so the renewal bills the SAME price the
275	          // order charged even if the admin retunes annual_discount_percent later.
276	          annualDiscountPct: quote.annualPct,
277	          wantsDedicatedIp: false,
278	          expiresAt: addMonths(new Date(), quote.term),
279	        } as Prisma.ServerUncheckedCreateInput,
280	      });
281	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
282	      return s;
283	    });
284	  } catch (e) {
285	    if (e instanceof InsufficientBalanceError) {
286	      throw new GameOrderError("Insufficient balance. Top up your wallet first.");
287	    }
288	    throw e;
289	  }
290	
291	  await db.auditLog.create({
292	    data: {
293	      userId: user.id,
294	      action: "gameserver.order",
295	      detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"}`,
296	    },
297	  });
298	  // Deploy-funnel COMPLETION — the game analogue of lib/order.ts placeOrder. The ONE
299	  // place a game order is created & paid, reached by BOTH the wallet path
300	  // (lib/actions-gameplans.ts) and the card path (lib/fulfil-checkout.ts webhook /
301	  // redirect), so every completed game deploy is counted once with a reliable userId.
302	  // Terminal event (drives the completed counts, not a wizard-step row); best-effort
303	  // and double-guarded so it can never disturb the money path.
304	  try {
305	    await recordDeployFunnelComplete({ product: "game", step: "Complete", stepIndex: 5, userId: user.id });
306	  } catch {
307	    /* never let funnel bookkeeping affect a completed order */
308	  }
309	  return server.id;
310	}
