83	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any; user: any }> {
84	  const server = await db.server.findUnique({
85	    where: { id: job.serverId! },
86	    // `user` (email) + `node` (publicIp) are needed for the deployment
87	    // confirmation email fired on provision success; the rest is used throughout.
