113	/**
114	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
115	 * plus any control-panel/app install script and selected add-ons. Long installs
116	 * run in the background so the VM reports ready promptly.
117	 */
118	function buildCloudInit(server: any): string {
119	  const addons = (server.addons ?? {}) as {
120	    malwareScanner?: boolean;
121	    dailyBackup?: boolean;
122	    docker?: boolean;
123	    claudeCode?: boolean;
124	  };
