593	/**
594	 * Tail the game service's recent logs. Resolves the unit from the family hints
595	 * (compile-time constants), then reads the last `n` journal lines; if journald has
596	 * nothing, falls back to a `.log` file under the data roots. Read-only.
597	 */
598	export async function readGameLogs(conn: Client, spec: GameControlSpec, n = 200): Promise<LogResult> {
599	  const lines = Math.min(Math.max(Math.trunc(n) || 200, 20), 500);
600	  const hints = spec.serviceHints.map(shq).join(" ");
601	  const roots = spec.dataRoots.map(shq).join(" ");
602	  const script = [
603	    `unit=""`,
604	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
605	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
606	    `echo "NXLOG:UNIT:${"$"}{unit:-none}"`,
607	    `if [ -n "$unit" ]; then journalctl -u "$unit" -n ${lines} --no-pager 2>/dev/null; fi`,
608	    // Fallback: newest *.log under the data roots (bounded).
609	    `f=""; for r in ${roots}; do [ -d "$r" ] && f=$(find "$r" -maxdepth 4 -type f -name '*.log' 2>/dev/null | head -1) && [ -n "$f" ] && break; done`,
610	    `if [ -n "$f" ]; then echo "NXLOG:FILE:$f"; tail -n ${lines} "$f" 2>/dev/null; fi`,
611	  ].join("\n");
612	  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
613	  const all = stdout.split(/\r?\n/);
614	  let unit: string | null = null;
615	  const out: string[] = [];
616	  for (const l of all) {
617	    const m = /^NXLOG:UNIT:(.*)$/.exec(l);
618	    if (m) {
619	      unit = m[1] === "none" ? null : m[1];
620	      continue;
621	    }
622	    if (/^NXLOG:FILE:/.test(l)) continue;
623	    out.push(l);
624	  }
625	  while (out.length && out[out.length - 1].trim() === "") out.pop();
626	  return { ok: true, lines: out.slice(-lines), unit };
627	}
