632	/** List the top-level world/save entries with sizes. Read-only. */
633	export async function readWorlds(conn: Client, spec: GameControlSpec): Promise<WorldResult> {
634	  const dir = await remoteLocateDir(conn, spec.dataRoots);
635	  if (!dir) return { ok: true, dir: null, entries: [] };
636	  // `du -sb` on each top-level entry: size<TAB>path. Bounded to 200 entries.
637	  const script =
638	    `cd ${shq(dir)} 2>/dev/null || exit 0; ` +
639	    `for e in * .*; do [ "$e" = "." ] || [ "$e" = ".." ] && continue; [ -e "$e" ] || continue; ` +
640	    `t=f; [ -d "$e" ] && t=d; sz=$(du -sb "$e" 2>/dev/null | cut -f1); printf '%s\\t%s\\t%s\\n' "$t" "${"$"}{sz:-0}" "$e"; done | head -200`;
641	  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
642	  const entries: WorldEntry[] = [];
643	  for (const line of stdout.split(/\r?\n/)) {
644	    const parts = line.split("\t");
645	    if (parts.length < 3) continue;
646	    const [t, sz, ...rest] = parts;
647	    const name = rest.join("\t").trim();
648	    if (!name) continue;
649	    entries.push({ name, sizeBytes: Number(sz) || 0, isDir: t === "d" });
650	  }
651	  return { ok: true, dir, entries };
652	}
