661	    `for f in "$d"/*.tar.gz; do [ -f "$f" ] || continue; ` +
662	    `sz=$(stat -c '%s' "$f" 2>/dev/null); mt=$(stat -c '%Y' "$f" 2>/dev/null); ` +
663	    `printf '%s\\t%s\\t%s\\n' "${"$"}{sz:-0}" "${"$"}{mt:-0}" "$f"; done | head -100`;
664	  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
665	  const backups: BackupEntry[] = [];
666	  for (const line of stdout.split(/\r?\n/)) {
667	    const parts = line.split("\t");
668	    if (parts.length < 3) continue;
669	    const path = parts.slice(2).join("\t").trim();
670	    if (!path || !isSafeRemotePath(path)) continue;
671	    backups.push({
672	      name: path.split("/").pop() || path,
673	      path,
674	      sizeBytes: Number(parts[0]) || 0,
675	      modifiedMs: (Number(parts[1]) || 0) * 1000,
676	    });
677	  }
678	  backups.sort((a, b) => b.modifiedMs - a.modifiedMs);
679	  return { ok: true, backups };
680	}
