688	/**
689	 * Parse the connected-player list out of a family's list-command RCON response.
690	 * Best-effort per family; unknown shapes return the raw response so the UI can
691	 * still show it.
692	 */
693	export function parsePlayers(family: GameFamily, response: string): { players: Player[]; raw: string } {
694	  const raw = response.trim();
695	  if (family === "minecraft") {
696	    // "There are 2 of a max of 20 players online: Alice, Bob"
697	    const m = /players online:\s*(.*)$/i.exec(raw);
698	    const names = m && m[1].trim() ? m[1].split(",").map((s) => s.trim()).filter(Boolean) : [];
699	    return { players: names.map((name) => ({ name })), raw };
700	  }
701	  if (family === "palworld") {
702	    // "name,playeruid,steamid" lines, first line is a header.
703	    const lines = raw.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
704	    const players: Player[] = [];
705	    for (const l of lines) {
706	      if (/^name\s*,/i.test(l)) continue;
707	      const cols = l.split(",");
708	      if (cols[0]) players.push({ name: cols[0].trim(), extra: cols.slice(1).join(",").trim() || undefined });
709	    }
710	    return { players, raw };
711	  }
712	  // cs2 `status` and anything else: hand back the raw block.
713	  return { players: [], raw };

