198	/**
199	 * Fire due scheduled restarts. Selects enabled GameSchedule rows whose `nextRunAt`
200	 * has passed, enqueues a GAME_POWER restart (announce=true) for each — subject to
201	 * the same guards a manual restart uses — and advances `nextRunAt` to the next day
202	 * so a schedule fires at most once per due time. Idempotent / safe on a timer.
203	 */
204	export async function gameScheduleSweep(): Promise<void> {
205	  const now = new Date();
206	  const due = await db.gameSchedule.findMany({
207	    where: { enabled: true, nextRunAt: { lte: now } },
208	    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
209	    take: 100,
210	  });
211	  if (due.length === 0) return;
212	
213	  for (const s of due) {
214	    // Always advance the clock first so a server that is down / mid-operation does
215	    // not cause the same row to be reselected every tick.
216	    const nextRunAt = computeNextRun(s.hour, s.minute, now);
217	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
218	
219	    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
220	    if (!isGameFamily(fam)) continue;
221	    if (s.server.status !== "RUNNING") continue;
222	
223	    const busy = await db.job.count({
224	      where: {
225	        serverId: s.server.id,
226	        status: { in: ["QUEUED", "RUNNING"] },
227	        type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
228	      },
229	    });
230	    if (busy > 0) continue;
231	
232	    await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
233	  }
234	}
